using System;
using System.Globalization;
using System.IO;
using System.Security.Cryptography;
using System.Text;

namespace LuminaDB.Core.Web
{
    /// <summary>
    /// phpMyAdmin for people coming from XAMPP (SPEC §5.13): off by default, served at http://phpmyadmin.localhost:&lt;port&gt;/.
    /// Settings proven in ParityTests\web (cookie login, 127.0.0.1 over TCP, a 32-character blowfish_secret, no outbound calls).
    /// The engine's phpmyadmin folder may be shared by several LuminaDB copies, so its config.inc.php is a small stub that
    /// loads this copy's generated file, named by the LUMINA_PMA_CONFIG variable LuminaDB gives php-cgi.
    /// </summary>
    public static class PhpMyAdminConfig
    {
        public const string Host = "phpmyadmin";
        public const string EnvVar = "LUMINA_PMA_CONFIG";
        public const string StubMarker = "LuminaDB phpMyAdmin stub";
        public const string OriginalName = "config.lumina-original.php";

        public static string ConfigFile(AppPaths p) => Path.Combine(p.Config, "lumina", "phpmyadmin.config.php");
        public static string SecretFile(AppPaths p) => Path.Combine(p.Config, "lumina", "phpmyadmin.secret");
        public static string TempDir(AppPaths p) => Path.Combine(p.Temp, "pma");

        /// <summary>
        /// With no root password phpMyAdmin opens straight in (as XAMPP does); with one, it asks for it (cookie login).
        /// The password is never written to a file.
        /// </summary>
        public static string Build(AppPaths paths, int mariaDbPort, bool rootHasPassword)
        {
            string Php(string s) => "'" + s.Replace("\\", "\\\\").Replace("'", "\\'") + "'";
            var sb = new StringBuilder();
            sb.AppendLine("<?php");
            sb.AppendLine("// Generated by LuminaDB whenever the web server or the root password changes. Don't edit: it is rewritten.");
            sb.AppendLine("declare(strict_types=1);");
            sb.AppendLine("$cfg['blowfish_secret'] = " + Php(Secret(paths)) + ";");
            sb.AppendLine("$i = 1;");
            if (rootHasPassword)
            {
                sb.AppendLine("$cfg['Servers'][$i]['auth_type'] = 'cookie';");
                sb.AppendLine("$cfg['Servers'][$i]['AllowNoPassword'] = false;");
            }
            else
            {
                sb.AppendLine("$cfg['Servers'][$i]['auth_type'] = 'config';");
                sb.AppendLine("$cfg['Servers'][$i]['user'] = 'root';");
                sb.AppendLine("$cfg['Servers'][$i]['password'] = '';");
                sb.AppendLine("$cfg['Servers'][$i]['AllowNoPassword'] = true;");
            }
            sb.AppendLine("$cfg['Servers'][$i]['host'] = '127.0.0.1';");
            sb.AppendLine("$cfg['Servers'][$i]['port'] = '" + mariaDbPort.ToString(CultureInfo.InvariantCulture) + "';");
            sb.AppendLine("$cfg['Servers'][$i]['connect_type'] = 'tcp';");
            sb.AppendLine("$cfg['Servers'][$i]['compress'] = false;");
            sb.AppendLine("$cfg['Servers'][$i]['verbose'] = 'LuminaDB';");
            sb.AppendLine("$cfg['TempDir'] = " + Php(TempDir(paths).Replace('\\', '/')) + ";");
            sb.AppendLine("$cfg['UploadDir'] = '';");
            sb.AppendLine("$cfg['SaveDir'] = '';");
            sb.AppendLine("$cfg['VersionCheck'] = false;");
            sb.AppendLine("$cfg['SendErrorReports'] = 'never';");
            sb.AppendLine("$cfg['DefaultLang'] = 'en';");
            sb.AppendLine("$cfg['ShowPhpInfo'] = false;");
            sb.AppendLine("$cfg['PmaNoRelation_DisableWarning'] = true;");
            sb.AppendLine("$cfg['ExecTimeLimit'] = 300;");
            return sb.ToString();
        }

        public static string Stub() =>
            "<?php\n" +
            "// " + StubMarker + ". Each LuminaDB copy keeps its own phpMyAdmin settings (config\\lumina\\phpmyadmin.config.php);\n" +
            "// this file loads the one belonging to the LuminaDB that runs PHP. The file that was here is " + OriginalName + ".\n" +
            "$luminaConfig = getenv('" + EnvVar + "');\n" +
            "if (is_string($luminaConfig) && $luminaConfig !== '' && is_file($luminaConfig)) {\n" +
            "    require $luminaConfig;\n" +
            "} elseif (is_file(__DIR__ . '/" + OriginalName + "')) {\n" +
            "    require __DIR__ . '/" + OriginalName + "';\n" +
            "}\n";

        /// <summary>Writes this copy's config and, once, the stub (keeping whatever config.inc.php was there).</summary>
        public static void Write(AppPaths paths, WebStack stack, int mariaDbPort, bool rootHasPassword)
        {
            Directory.CreateDirectory(TempDir(paths));
            Directory.CreateDirectory(Path.GetDirectoryName(ConfigFile(paths)));
            File.WriteAllText(ConfigFile(paths), Build(paths, mariaDbPort, rootHasPassword), new UTF8Encoding(false));
            if (!stack.HasPhpMyAdmin) return;
            var target = Path.Combine(stack.PhpMyAdminDir, "config.inc.php");
            try
            {
                if (File.Exists(target))
                {
                    var text = File.ReadAllText(target);
                    if (text.Contains(StubMarker)) return;
                    var original = Path.Combine(stack.PhpMyAdminDir, OriginalName);
                    if (!File.Exists(original)) File.Copy(target, original);
                }
                File.WriteAllText(target, Stub(), new UTF8Encoding(false));
            }
            catch (Exception ex) when (ex is IOException || ex is UnauthorizedAccessException)
            {
                throw new LuminaException(ErrorKind.FolderNotWritable,
                    "LuminaDB can't write phpMyAdmin's settings file in " + stack.PhpMyAdminDir + ". Move LuminaDB to a folder you own.", ex);
            }
        }

        /// <summary>32 random characters, made once per LuminaDB copy (phpMyAdmin encrypts its login cookie with it).</summary>
        private static string Secret(AppPaths paths)
        {
            var file = SecretFile(paths);
            try
            {
                if (File.Exists(file))
                {
                    var s = File.ReadAllText(file).Trim();
                    if (s.Length == 32) return s;
                }
            }
            catch (IOException) { }
            const string chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
            var bytes = new byte[32];
            using (var rng = RandomNumberGenerator.Create()) rng.GetBytes(bytes);
            var sb = new StringBuilder(32);
            foreach (var b in bytes) sb.Append(chars[b % chars.Length]);
            Directory.CreateDirectory(Path.GetDirectoryName(file));
            File.WriteAllText(file, sb.ToString(), new UTF8Encoding(false));
            return sb.ToString();
        }
    }
}
